import React from "react";
import { useState } from "react";

const BookingForm = (props) => {
   const [occasion, setOccasion] = useState("");
   const [guests, setGuests] = useState("");
   const [date, setDate] = useState("");
   const [times, setTimes] = useState("");

   const handleSumbit = (e) => {
      e.preventDefault();
      props.submitForm(e);
   };

   const handleChange = (e) => {
      setDate(e);
      props.dispatch(e);
   };

   return (
      <header>
         <section>
            <form onSubmit={handleSumbit}>
               <fieldset className="formField">
                  <div>
                     <label htmlFor="book-date">Elige la fecha:</label>
                     <input
                        id="book-date"
                        value={date}
                        onChange={(e) => handleChange(e.target.value)}
                        type="date"
                        required
                     />
                  </div>
                  <div>
                     <label htmlFor="book-time">Elige la hora:</label>
                     <select
                        id="book-time"
                        value={times}
                        onChange={(e) => setTimes(e.target.value)}
                        required
                     >
                        <option value="">Selecciona una hora</option>
                        {props.availableTimes.availableTimes.map((availableTimes) => {
                           return <option key={availableTimes}>{availableTimes}</option>;
                        })}
                     </select>
                  </div>
                  <div>
                     <label htmlFor="book-guests">Número de invitados:</label>
                     <input
                        id="book-guests"
                        min="1"
                        value={guests}
                        onChange={(e) => {
                           setGuests(e.target.value);
                        }}
                        type={"number"}
                        placeholder={0}
                        max={10}
                        required
                     />
                  </div>
                  <div>
                     <label htmlFor="book-occasion">Ocasión:</label>
                     <select
                        id="book-occasion"
                        key={occasion}
                        value={occasion}
                        onChange={(e) => setOccasion(e.target.value)}
                        required
                     >
                        <option value="">Selecciona una opción</option>
                        <option>Cumpleaños</option>
                        <option>Aniversario</option>
                     </select>
                  </div>
                  <div className="btnReceive">
                     <input
                        aria-label="On Click"
                        type={"submit"}
                        value={"Hacer tu reserva"}
                     />
                  </div>
               </fieldset>
            </form>
         </section>
      </header>
   );
};

export default BookingForm;
